require "import"
import "android.app.*"
import "android.os.*"
import "android.widget.*"
import "android.view.*"
import "android.content.*"
import "android.webkit.*"
import "android.graphics.Typeface"
import "android.speech.tts.TextToSpeech"
import "java.util.Locale"
import "com.androlua.LuaDialog"

local ctx = activity

local ttsListo = false
local ttsIdioma = false
local tts = TextToSpeech(activity, TextToSpeech.OnInitListener{
  onInit = function(s) if s == TextToSpeech.SUCCESS then ttsListo = true end end
})

function hablar(texto)
  if tts then
    if ttsListo and not ttsIdioma then pcall(function() tts.setLanguage(Locale("es", "ES")) end) ttsIdioma = true end
    pcall(function() tts.speak(tostring(texto), 1, nil, nil) end)
  end
end

local rutaJuego = activity.getFilesDir().getAbsolutePath() .. "/juego-aviones.html"
local dlgJuego = nil
local webJuego = nil
local vibrator = ctx.getSystemService(Context.VIBRATOR_SERVICE)

local function archivoExiste()
  local existe = false
  pcall(function()
    local f = io.open(rutaJuego, "rb")
    if f then
      if f:read(1) then existe = true end
      f:close()
    end
  end)
  return existe
end

local function guardarJuego()
  local ok = false
  pcall(function()
    local f = io.open(rutaJuego, "w")
    if f then
      f:write(htmlJuego)
      f:close()
      ok = true
    end
  end)
  return ok
end

local function cargarJuego()
  if not webJuego then return end
  pcall(function()
    webJuego.loadUrl("file://" .. rutaJuego)
  end)
end

local function cerrarJuego()
  pcall(function()
    if webJuego then
      webJuego.stopLoading()
      webJuego.loadUrl("about:blank")
      webJuego.destroy()
      webJuego = nil
    end
  end)
  pcall(function() if dlgJuego then dlgJuego.dismiss() end end)
  pcall(function() if tts then tts.shutdown() end end)
end

