local htmlJuego = table.concat(partes)

local layoutJuego = {
LinearLayout, orientation = "1", layout_width = "-1", layout_height = "-1", backgroundColor = 0xFF121217,
{ LinearLayout, orientation = "0", layout_width = "-1",
  { TextView, text = "Juego de Aviones", textSize = "18sp", textColor = 0xFFFFFFFF, typeface = Typeface.DEFAULT_BOLD, gravity = "1", layout_weight = 1, layout_width = "0", padding = "8dp" },
  { Button, id = "btn_cerrar_juego", text = "X", textSize = "20sp", textColor = 0xFFFFFFFF, layout_width = "50dp", height = "45dp" },
},
{ WebView, id = "web_juego", layout_width = "-1", layout_height = "0dp", layout_weight = 1 },
}

dlgJuego = Dialog(ctx, android.R.style.Theme_Black_NoTitleBar_Fullscreen)
dlgJuego.setContentView(loadlayout(layoutJuego))

pcall(function()
  local aj = web_juego.getSettings()
  aj.setJavaScriptEnabled(true)
  aj.setDomStorageEnabled(true)
  aj.setAllowFileAccess(true)
  aj.setAllowFileAccessFromFileURLs(true)
  aj.setAllowUniversalAccessFromFileURLs(true)
  aj.setMediaPlaybackRequiresUserGesture(false)
  aj.setCacheMode(WebSettings.LOAD_DEFAULT)
  web_juego.setWebViewClient(WebViewClient())
  web_juego.setWebChromeClient(WebChromeClient())
end)

webJuego = web_juego

btn_cerrar_juego.onClick = function()
  vibrator.vibrate(100)
  cerrarJuego()
end

pcall(function()
  dlgJuego.setOnKeyListener(DialogInterface.OnKeyListener{
    onKey = function(dialog, keyCode, event)
      if keyCode == KeyEvent.KEYCODE_BACK and event.getAction() == KeyEvent.ACTION_UP then
        cerrarJuego()
        return true
      end
      return false
    end
  })
end)

dlgJuego.show()
if archivoExiste() then
  cargarJuego()
else
  if guardarJuego() then
    cargarJuego()
  else
    hablar("No se pudo guardar el juego en el teléfono.")
  end
end
